static bool MimeThisIsStartPart(MimeObject* obj, MimeObject* child) {
  bool rval = false;
  char *ct, *st, *cst;

  ct = MimeHeaders_get(obj->headers, HEADER_CONTENT_TYPE, false, false);
  st = (ct ? MimeHeaders_get_parameter(ct, HEADER_PARM_START, NULL, NULL) : 0);

  PR_FREEIF(ct);
  if (!st) return false;

  // Strip angle brackets from the start parameter value per RFC 2387.
  char* stStripped = st;
  if (*stStripped == '<') {
    stStripped++;
    int stLen = strlen(stStripped);
    if (stLen > 0 && stStripped[stLen - 1] == '>') {
      stStripped[stLen - 1] = '\0';
    }
  }

  cst = MimeHeaders_get(child->headers, HEADER_CONTENT_ID, false, false);
  if (!cst)
    rval = false;
  else {
    char* tmp = cst;
    if (*tmp == '<') {
      int length;
      tmp++;
      length = strlen(tmp);
      if (length > 0 && tmp[length - 1] == '>') {
        tmp[length - 1] = '\0';
      }
    }

    rval = (!strcmp(stStripped, tmp));
  }

  PR_FREEIF(st);
  PR_FREEIF(cst);
  return rval;
}
